35. function Write-JsonStore {
36.     param(
37.         [Parameter(Mandatory)][string]$Path,
38.         [Parameter(Mandatory)][AllowEmptyCollection()][object[]]$Items
39.     )
40. 
41.     $parent = Split-Path -Parent $Path
